head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getVisibleRowNum]<br/>Body 영역에 렌더링 된 데이터 Row 의 갯수를 반환합니다.",
    "validation" : [
        "visibleRowNum 속성과 연관은 있지만 visibleRowNum 속성값을 반환하지 않습니다.",
        "Body 영역(뷰포트)에 실제 렌더링된 데이터 Row 의 수를 반환합니다.",
        "Header, Footer, SubTotal Row 는 반환값에 포함되지 않습니다.",
        "필터링에 의해 렌더링 되지 않는 데이터 Row 는 반환값에 포함되지 않습니다.",
        "데이터가 렌더링되지 않은 초기 상태이거나 데이터가 없으면 0 을 반환합니다.",
        "visibleRowNum='all' 이면 모든 데이터가 렌더링되므로 getVisibleRowNum() 와 getDataLength() 반환값이 같을 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성 (10 행 — visibleRowNum 값에 따라 렌더 Row 수 차이가 보이도록 충분히 많은 데이터 확보)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 10);

    // 조건 설정 (visibleRowNum 미설정 시 '' → createCList 가 빈 문자열 속성을 제외하므로 Property 미설정 상태로 생성)
    let properties = {
        visibleRowNum: con_visibleRowNum.getValue(),
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // 디자인 높이를 작게(약 3행) 설정 → 미설정('') 시 뷰포트에 맞는 Row 수만 렌더링되어 getVisibleRowNum 으로 확인 가능
    // 마지막 컬럼 width='*' 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:171px;">';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);

    scwin.btn_getVisibleRowNum_onclick();
}



// getVisibleRowNum 확인 — Body 뷰포트에 렌더링된 데이터 Row 수 반환 (Header/Footer/SubTotal 미포함)
// @spec : visibleRowNum='all' 이면 getDataLength() 와 같을 수 있으므로 비교 출력
scwin.btn_getVisibleRowNum_onclick = function (e) {
    let conVal = con_visibleRowNum.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("설정한 visibleRowNum(con) : '" + conVal + "' (속성값과 반환값은 다를 수 있음)");
    wf_body_bottom.getObj("scwin").setReturnValue("getVisibleRowNum() (Body 영역에 렌더링된 데이터 Row 수) : " + target1.getVisibleRowNum());
    wf_body_bottom.getObj("scwin").setReturnValue("getDataLength() (전체 데이터 Row 수) : " + target1.getDataLength());
    wf_body_bottom.getObj("scwin").setReturnValue("[all 일 때 getVisibleRowNum() === getDataLength()] : " + (target1.getVisibleRowNum() === target1.getDataLength()));
}



// 필터 적용 — col1 컬럼을 'col1_1' 로 정확히 일치 필터링 → 1개 Row 만 렌더링
// 필터링에 의해 렌더링되지 않는 데이터 Row 는 getVisibleRowNum() 반환값에 미포함됨을 확인
scwin.btn_setColumnFilter_onclick = function (e) {
    dlt_bind.setColumnFilter({ type: "row", colIndex: "col1", key: "col1_1", condition: "and", exactMatch: true });

    wf_body_bottom.getObj("scwin").setReturnValue("[필터 col1=col1_1 적용] getVisibleRowNum() : " + target1.getVisibleRowNum());
    wf_body_bottom.getObj("scwin").setReturnValue("[필터 적용 후] getDataLength() : " + target1.getDataLength());
}
